jobs.command:
select net.http_post(
  url := (
    select decrypted_secret
    from vault.decrypted_secrets
    where name='privacy_export_project_url'
  ) || '/functions/v1/privacy-export-cleanup',
  headers := jsonb_build_object(
    'Content-Type','application/json',
    'x-cleanup-secret',(
      select decrypted_secret
      from vault.decrypted_secrets
      where name='privacy_export_cleanup_secret'
    )
  ),
  body := '{}'::jsonb
);
